#!/usr/bin/env bash
# Turns a `scripts/deploy.sh` deployment into a runnable stack: starts Postgres, writes the
# repo-root `.env` every service reads (and `apps/console/.env`), applies migrations, and seeds
# the lender/borrower parties and the test RWA from that deploy's output.
#
# Usage:
#   scripts/dev-setup.sh [network]     # network defaults to `testnet`
#
# Needs `.env.<network>-deploy` (generated by running `scripts/deploy.sh <network>` first;
# note that the reference deployment in TESTNET_DEPLOYMENT.md is read-only for outsiders)
# and the `stellar` CLI identities that deploy created (`keeper`, `price_publisher`, ...). Safe
# to re-run: secrets already in `.env` are kept, the seed is idempotent, and the Postgres
# container is reused.
#
# After this: `pnpm dev` starts every service and the console; `scripts/e2e-services.sh` drives
# the whole stack end to end.

set -euo pipefail
cd "$(dirname "$0")/.."

NETWORK=${1:-testnet}
DEPLOY_FILE=".env.${NETWORK}-deploy"
PG_CONTAINER=ballast-pg
PG_PORT=${BALLAST_PG_PORT:-5432}

log() { echo ">>> $*"; }

[[ -f "$DEPLOY_FILE" ]] || { echo "!!! $DEPLOY_FILE not found - run scripts/deploy.sh $NETWORK first" >&2; exit 1; }
# shellcheck source=/dev/null
source "$DEPLOY_FILE"

case "$NETWORK" in
  testnet)
    RPC_URL=https://soroban-testnet.stellar.org
    HORIZON_URL=https://horizon-testnet.stellar.org
    PASSPHRASE="Test SDF Network ; September 2015" ;;
  local)
    RPC_URL=http://localhost:8000/soroban/rpc
    HORIZON_URL=http://localhost:8000
    PASSPHRASE="Standalone Network ; February 2017" ;;
  *) echo "!!! unsupported network '$NETWORK' (expected testnet or local)" >&2; exit 1 ;;
esac

# --- Postgres -------------------------------------------------------------------------------
if command -v docker >/dev/null 2>&1; then ENGINE=docker
elif command -v podman >/dev/null 2>&1; then ENGINE=podman
else echo "!!! need docker or podman to run Postgres (or start your own and re-run)" >&2; exit 1
fi

if "$ENGINE" container inspect "$PG_CONTAINER" >/dev/null 2>&1; then
  log "Starting existing Postgres container ($PG_CONTAINER)"
  "$ENGINE" start "$PG_CONTAINER" >/dev/null
else
  log "Creating Postgres container ($PG_CONTAINER) on port $PG_PORT"
  "$ENGINE" run -d --name "$PG_CONTAINER" \
    -e POSTGRES_USER=ballast -e POSTGRES_PASSWORD=ballast -e POSTGRES_DB=ballast \
    -p "${PG_PORT}:5432" docker.io/library/postgres:16 >/dev/null
fi

log "Waiting for Postgres"
# Over TCP on purpose: during first-boot init the server only listens on its unix socket and then
# restarts, so a socket check can pass moments before the database goes away again.
pg_ready() { "$ENGINE" exec "$PG_CONTAINER" pg_isready -h 127.0.0.1 -U ballast -d ballast >/dev/null 2>&1; }
for _ in $(seq 1 60); do
  if pg_ready; then break; fi
  sleep 1
done
pg_ready || { echo "!!! Postgres did not become ready" >&2; exit 1; }

# PG_DB names the database inside the container. A fresh testnet deploy has new contract ids, so
# its lines, assets and parties must not mix with an older deploy's rows: give it its own database
# (PG_DB=ballast_2 scripts/dev-setup.sh testnet) and the old one is left exactly as it was.
PG_DB=${PG_DB:-ballast}
if ! "$ENGINE" exec "$PG_CONTAINER" psql -h 127.0.0.1 -U ballast -d ballast -tAc \
  "SELECT 1 FROM pg_database WHERE datname='${PG_DB}'" | grep -q 1; then
  log "Creating database ${PG_DB}"
  "$ENGINE" exec "$PG_CONTAINER" psql -h 127.0.0.1 -U ballast -d ballast -qc "CREATE DATABASE \"${PG_DB}\"" >/dev/null
fi

# --- .env -----------------------------------------------------------------------------------
# Keeps a value already in .env (so sessions and the SEP-10 identity survive a re-run), else
# falls back to the generated default.
keep() {
  local key=$1 fallback=$2 existing=""
  if [[ -f .env ]]; then existing=$(grep -E "^${key}=" .env | head -1 | cut -d= -f2- || true); fi
  if [[ -n "$existing" ]]; then echo "$existing"; else echo "$fallback"; fi
}

ensure_identity() {
  local name=$1
  if ! stellar keys address "$name" >/dev/null 2>&1; then
    log "Generating and funding CLI identity '$name'"
    stellar keys generate "$name" --network "$NETWORK" --fund -q
  fi
}

# The SEP-10 server key only signs auth challenges - it never needs to exist on-chain.
if ! stellar keys address ballast_sep10 >/dev/null 2>&1; then
  stellar keys generate ballast_sep10 -q
fi
ensure_identity payout_hop

# Ports are kept from an existing .env too, so moving one off a port another project is using
# (edit .env, re-run this script to carry it into apps/console/.env) sticks.
API_PORT=$(keep API_PORT 3000)
ISSUER_GATEWAY_PORT=$(keep ISSUER_GATEWAY_PORT 3001)
PAYOUT_HOP_PORT=$(keep PAYOUT_HOP_PORT 3002)

JWT_SIGNING_SECRET=$(keep JWT_SIGNING_SECRET "$(openssl rand -hex 32)")
WEBHOOK_SECRET_KEY=$(keep WEBHOOK_SECRET_KEY "$(openssl rand -hex 32)")
API_KEY_SECRET_KEY=$(keep API_KEY_SECRET_KEY "$(openssl rand -hex 32)")
INTERNAL_API_TOKEN=$(keep INTERNAL_API_TOKEN "$(openssl rand -hex 32)")

# Real price sources for the test asset (see scripts/real-sources.env).
# shellcheck source=/dev/null
source scripts/real-sources.env

log "Writing .env"
umask 077
cat > .env <<EOF
# Generated by scripts/dev-setup.sh for the '$NETWORK' deployment in $DEPLOY_FILE.
# Holds operator secret keys - never commit it (it's in .gitignore).

DATABASE_URL=postgres://ballast:ballast@localhost:${PG_PORT}/${PG_DB}

# Node tries IPv4 and IPv6 in turn and gives each attempt only 250ms by default; on a slow link
# (or one with no IPv6 route) every attempt times out and RPC calls fail with ETIMEDOUT even
# though the endpoint is reachable. Give each attempt a realistic budget instead.
NODE_OPTIONS=--network-family-autoselection-attempt-timeout=5000

STELLAR_NETWORK=$NETWORK
STELLAR_RPC_URL=$RPC_URL
STELLAR_HORIZON_URL=$HORIZON_URL
STELLAR_NETWORK_PASSPHRASE="$PASSPHRASE"
STELLAR_SIMULATION_SOURCE=$ADMIN
STELLAR_POKE_SOURCE=$KEEPER

REGISTRY_CONTRACT_ID=$REGISTRY_CID
PRICE_GUARD_CONTRACT_ID=$PRICE_GUARD_CID
PLEDGE_VAULT_CONTRACT_ID=$PLEDGE_VAULT_CID
CREDIT_LINE_CONTRACT_ID=$CREDIT_LINE_CID
EXIT_DESK_CONTRACT_ID=$EXIT_DESK_CID
REPO_DVP_CONTRACT_ID=$REPO_DVP_CID
USDC_SAC_CONTRACT_ID=$USDC_SAC

API_PORT=$API_PORT
ISSUER_GATEWAY_PORT=$ISSUER_GATEWAY_PORT
PAYOUT_HOP_PORT=$PAYOUT_HOP_PORT
JWT_SIGNING_SECRET=$JWT_SIGNING_SECRET
WEBHOOK_SECRET_KEY=$WEBHOOK_SECRET_KEY
API_KEY_SECRET_KEY=$API_KEY_SECRET_KEY
INTERNAL_API_TOKEN=$INTERNAL_API_TOKEN
# payout-hop may pay only these accounts, in this USDC, up to the cap. In dev the "anchors" are the
# test lender and borrower.
PAYOUT_HOP_USDC_ISSUER=$USDC_ISSUER
PAYOUT_HOP_ALLOWED_DESTINATIONS=$LENDER,$BORROWER
PAYOUT_HOP_MAX_AMOUNT=5000
SEP10_SERVER_SECRET=$(stellar keys secret ballast_sep10)
SEP10_HOME_DOMAIN=localhost
SEP10_WEB_AUTH_DOMAIN=localhost
CONSOLE_ORIGIN=http://localhost:5173
ENABLE_DEV_LOGIN=false

KEEPER_SIGNER_MODE=local
PRICE_PUBLISHER_SIGNER_MODE=local
PAYOUT_HOP_SIGNER_MODE=local
KEEPER_SECRET_KEY=$(stellar keys secret keeper)
PRICE_PUBLISHER_SECRET_KEY=$(stellar keys secret price_publisher)
PAYOUT_HOP_SECRET_KEY=$(stellar keys secret payout_hop)

# Dev cadence: every keeper job each minute (production defaults are 5 minutes / hourly).
KEEPER_CURE_EXPIRY_CRON="* * * * *"
KEEPER_REPO_UNWIND_CRON="* * * * *"
KEEPER_REPO_MARGIN_CRON="* * * * *"

# RWA1 is priced as Etherfuse's real USTRY bond: Etherfuse's price API for the issuer NAV and
# RedStone's USTRY feed (read from mainnet) as the independent source.
REDSTONE_RPC_URL=$REDSTONE_RPC_URL
REDSTONE_NETWORK_PASSPHRASE="$REDSTONE_NETWORK_PASSPHRASE"
REDSTONE_FEED_CONTRACT_IDS='$REDSTONE_FEED_CONTRACT_IDS'
ISSUER_NAV_SYMBOLS='$ISSUER_NAV_SYMBOLS'
EOF

cat > apps/console/.env <<EOF
VITE_API_URL=http://localhost:$API_PORT
VITE_STELLAR_NETWORK_PASSPHRASE="$PASSPHRASE"
EOF

# --- schema + seed --------------------------------------------------------------------------
log "Applying migrations"
pnpm --filter @ballast/db migrate

log "Seeding parties and the test asset from $DEPLOY_FILE"
set -a
# shellcheck source=/dev/null
source "$DEPLOY_FILE"
set +a
pnpm --filter @ballast/db seed

log "Done. Next: 'pnpm dev' (all services + console), then 'scripts/e2e-services.sh'."
